SELECT ?predicate
       (COUNT(*) AS ?occurrences)
       (COUNT(DISTINCT ?s) AS ?subjects)
       (SAMPLE(?o) AS ?sample)
WHERE {
  GRAPH <https://lindas.admin.ch/foj/zefix> {
    ?s a <https://schema.ld.admin.ch/ZefixOrganisation> .
    ?s ?predicate ?o .
  }
}
GROUP BY ?predicate
ORDER BY DESC(?occurrences)
LIMIT 40

